package com.medtrack.inventory.entity;
import com.medtrack.batch.entity.Batch; import com.medtrack.warehouse.entity.Warehouse; import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="inventory_ledger_lines") public class InventoryLedgerLine { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="journal_entry_id",nullable=false) private InventoryJournalEntry journalEntry; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="batch_id",nullable=false) private Batch batch; @Enumerated(EnumType.STRING) @Column(name="account_type",nullable=false) private AccountType accountType; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="warehouse_id") private Warehouse warehouse; @Enumerated(EnumType.STRING) @Column(nullable=false) private LedgerDirection direction; @Column(nullable=false) private int quantity; @Column(name="available_before") private Integer availableBefore; @Column(name="available_delta") private Integer availableDelta; @Column(name="available_after") private Integer availableAfter; @Column(name="reserved_before") private Integer reservedBefore; @Column(name="reserved_delta") private Integer reservedDelta; @Column(name="reserved_after") private Integer reservedAfter; @Column(name="quarantined_before") private Integer quarantinedBefore; @Column(name="quarantined_delta") private Integer quarantinedDelta; @Column(name="quarantined_after") private Integer quarantinedAfter; @Column(name="balance_after") private Integer balanceAfter; protected InventoryLedgerLine(){} private InventoryLedgerLine(Batch batch,AccountType account,Warehouse warehouse,LedgerDirection direction,int quantity){if(quantity<=0)throw new IllegalArgumentException("Ledger quantity must be positive");this.batch=batch;accountType=account;this.warehouse=warehouse;this.direction=direction;this.quantity=quantity;} public static InventoryLedgerLine physical(Batch b,Warehouse w,LedgerDirection d,int q,InventoryBalance before,int availableDelta,int reservedDelta,int quarantinedDelta){InventoryLedgerLine l=new InventoryLedgerLine(b,AccountType.WAREHOUSE_ACTIVE,w,d,q);l.availableBefore=before.getAvailableQuantity();l.availableDelta=availableDelta;l.availableAfter=l.availableBefore+availableDelta;l.reservedBefore=before.getReservedQuantity();l.reservedDelta=reservedDelta;l.reservedAfter=l.reservedBefore+reservedDelta;l.quarantinedBefore=before.getQuarantinedQuantity();l.quarantinedDelta=quarantinedDelta;l.quarantinedAfter=l.quarantinedBefore+quarantinedDelta;l.balanceAfter=l.availableAfter+l.reservedAfter+l.quarantinedAfter;return l;} public static InventoryLedgerLine offset(Batch b,AccountType account,LedgerDirection direction,int q){return new InventoryLedgerLine(b,account,null,direction,q);} void setJournalEntry(InventoryJournalEntry e){journalEntry=e;} public LedgerDirection getDirection(){return direction;} public int getQuantity(){return quantity;} }
